// @edit/extract — canonical product extraction.
//
// Pure and DOM-adapter based: every function takes an explicit `doc`
// (a Document) and `loc` ({ href, hostname }) instead of touching the
// browser `document`/`location` globals. This lets the exact same code
// run under jsdom in unit tests AND, after inlining, inside the extension
// content script (see packages/extract/build.mjs).
//
// Extraction priority (kept in sync with the handoff brief §4):
//   name:     JSON-LD Product.name -> og:title -> document.title
//   price:    JSON-LD offers.price/lowPrice -> product:price:amount
//             -> og:price:amount -> DOM heuristic
//   currency: JSON-LD priceCurrency -> product:price:currency
//             -> og:price:currency
//   image:    JSON-LD image -> og:image -> biggest <img>
//   brand:    JSON-LD brand.name -> product:brand
//   site:     og:site_name -> domain-derived
//
// A domain-rule layer (see applyRules) runs after the generic pass so
// curated per-site rules can fill or override fields on sites whose
// structured data is thin.

export function jsonLdProducts(doc) {
  const out = [];
  const nodes = doc.querySelectorAll('script[type="application/ld+json"]');
  nodes.forEach((n) => {
    let data;
    try { data = JSON.parse(n.textContent); } catch { return; }
    const stack = Array.isArray(data) ? [...data] : [data];
    while (stack.length) {
      const o = stack.pop();
      if (!o || typeof o !== "object") continue;
      if (Array.isArray(o["@graph"])) stack.push(...o["@graph"]);
      const t = o["@type"];
      const isProduct = t === "Product" || (Array.isArray(t) && t.includes("Product"));
      if (isProduct) out.push(o);
    }
  });
  return out;
}

export function metaContent(doc, sel) {
  const el = doc.querySelector(sel);
  return el ? (el.getAttribute("content") || "").trim() : "";
}

export function firstOffer(prod) {
  let off = prod.offers;
  if (Array.isArray(off)) off = off[0];
  if (off && off["@type"] === "AggregateOffer") return off;
  return off || null;
}

export function pickPriceFromDom(doc) {
  // last-resort heuristic: find a visible price-like number
  const sel = '[itemprop="price"],[class*="price" i],[class*="Price" i],[id*="price" i]';
  const els = Array.from(doc.querySelectorAll(sel)).slice(0, 40);
  for (const el of els) {
    const txt = (el.getAttribute("content") || el.textContent || "").trim();
    const m = txt.replace(/,/g, "").match(/(?:¥|\$|€|£|￥)?\s*([0-9]{2,9}(?:\.[0-9]{1,2})?)/);
    if (m && Number(m[1]) >= 100) return m[1];
  }
  return "";
}

// Resolve a possibly relative / protocol-relative URL against the page.
export function absUrl(u, base) {
  if (!u) return "";
  try { return new URL(u, base).href; } catch { return u; }
}

// Resolve the best URL for an <img>, tolerating lazy-loading patterns.
function imgSrc(img) {
  const direct = img.currentSrc || img.getAttribute("src") ||
    img.getAttribute("data-src") || img.getAttribute("data-original") ||
    img.getAttribute("data-lazy-src") || img.getAttribute("data-image") || "";
  if (/^https?:/.test(direct)) return direct;
  const ss = img.getAttribute("srcset") || img.getAttribute("data-srcset") || "";
  if (ss) {
    const urls = ss.split(",").map((s) => s.trim().split(/\s+/)[0]).filter((u) => /^https?:/.test(u));
    if (urls.length) return urls[urls.length - 1]; // usually the largest
  }
  return "";
}

export function biggestImage(doc) {
  let best = "", area = 0, lazyFallback = "";
  doc.querySelectorAll("img").forEach((img) => {
    const src = imgSrc(img);
    if (!src) return;
    const a = (img.naturalWidth || img.width || 0) * (img.naturalHeight || img.height || 0);
    if (a > area) { area = a; best = src; }
    if (!lazyFallback && !/sprite|icon|logo|blank|placeholder|1x1/i.test(src)) lazyFallback = src;
  });
  // Prefer a properly-sized image; otherwise a plausible lazy one (area 0).
  return area > 40000 ? best : (lazyFallback || best);
}

// ---- Shopify enrichment ----------------------------------------------------
// Many brand-official stores run Shopify but ship thin page metadata (no
// og:image / JSON-LD). Shopify exposes clean product JSON at `<product-url>.js`,
// which these helpers turn into our item shape. The fetch itself happens in the
// content script (same-origin) or the popup re-check; these stay pure/testable.

// Build the `<product>.js` URL from a product page URL, or "" if not a product.
export function shopifyProductJsonUrl(href) {
  try {
    const u = new URL(href);
    // Shopify product URLs are exactly /products/<handle> (handle = last segment).
    // Excludes /products/detail/123 (EC-CUBE etc.) which is NOT Shopify.
    const m = u.pathname.match(/^(.*\/products\/[^/?#]+)\/?$/);
    return m ? u.origin + m[1] + ".js" : "";
  } catch { return ""; }
}


// Pull the size list from a Shopify product's options/variants.
export function shopifySizes(p) {
  const opts = Array.isArray(p && p.options) ? p.options : [];
  let sizeIdx = -1, values = [];
  opts.forEach((o, i) => {
    const name = typeof o === "string" ? o : (o && o.name) || "";
    if (/size|サイズ|size|寸/i.test(name)) { sizeIdx = i; if (o && Array.isArray(o.values)) values = o.values.slice(); }
  });
  if (values.length) return values.join(", ");
  const variants = Array.isArray(p && p.variants) ? p.variants : [];
  if (sizeIdx >= 0 && variants.length) {
    const key = "option" + (sizeIdx + 1);
    const set = [...new Set(variants.map((v) => v && v[key]).filter(Boolean))];
    if (set.length) return set.join(", ");
  }
  if (opts.length === 1 && variants.length) { // single-option product: use variant titles
    const set = [...new Set(variants.map((v) => v && (v.option1 || v.title)).filter((t) => t && t !== "Default Title"))];
    if (set.length) return set.join(", ");
  }
  return "";
}

// Available colors from a Shopify product's Color/カラー/色 option.
export function shopifyColors(p) {
  const opts = Array.isArray(p && p.options) ? p.options : [];
  for (let i = 0; i < opts.length; i++) {
    const o = opts[i];
    const name = typeof o === "string" ? o : (o && o.name) || "";
    if (/colou?r|カラー|色/i.test(name)) {
      if (o && Array.isArray(o.values)) return [...new Set(o.values)].join(", ");
      const variants = Array.isArray(p.variants) ? p.variants : [];
      const set = [...new Set(variants.map((v) => v && v["option" + (i + 1)]).filter(Boolean))];
      if (set.length) return set.join(", ");
    }
  }
  return "";
}

// Per-size availability from a Shopify product's variants (stock differs by size).
// Returns { "M": "instock", "L": "outofstock", … }.
export function shopifyAvailBySize(p) {
  const opts = Array.isArray(p && p.options) ? p.options : [];
  let sizeIdx = -1;
  opts.forEach((o, i) => { const name = typeof o === "string" ? o : (o && o.name) || ""; if (/size|サイズ|寸/i.test(name)) sizeIdx = i; });
  const variants = Array.isArray(p && p.variants) ? p.variants : [];
  const out = {};
  const mark = (s, v) => { const k = String(s || "").trim(); if (!k || k === "Default Title") return; out[k] = v && v.available === false ? "outofstock" : "instock"; };
  if (sizeIdx >= 0) { const key = "option" + (sizeIdx + 1); variants.forEach((v) => mark(v && v[key], v)); }
  else if (opts.length === 1) { variants.forEach((v) => mark(v && (v.option1 || v.title), v)); }
  return out;
}

// Map a parsed Shopify product-JSON object to a partial item.
export function shopifyFromJson(p, opts = {}) {
  if (!p || typeof p !== "object") return null;
  const code = String(opts.currency || "").toUpperCase();
  // Shopify's AJAX (.js) price is ALWAYS integer × 100 — even for JPY
  // (verified: LEMAIRE €590→59000, kindal ¥198,550→19855000). Always /100.
  const img = p.featured_image || (Array.isArray(p.images) && p.images[0]) || "";
  return {
    name: p.title ? String(p.title) : "",
    brand: p.vendor ? String(p.vendor) : "",
    price: p.price != null && !isNaN(Number(p.price)) ? String(Math.round(Number(p.price) / 100)) : "",
    currency: code,
    image: img ? absUrl(img, opts.href || "") : "",
    availability: p.available === true ? "instock" : (p.available === false ? "outofstock" : ""),
    sizes: shopifySizes(p),
    colors: shopifyColors(p),
    availBySize: shopifyAvailBySize(p),
  };
}

